class BookMyShow(private val n:Int,private val m:Int){private var first=0;private val remaining=IntArray(n){m};private val maximum=IntArray(4*n);private val sum=LongArray(4*n);init{build(1,0,n-1)}private fun build(node:Int,left:Int,right:Int){if(left==right){maximum[node]=m;sum[node]=m.toLong();return};val middle=(left+right)/2;build(node*2,left,middle);build(node*2+1,middle+1,right);pull(node)}private fun pull(node:Int){maximum[node]=maxOf(maximum[node*2],maximum[node*2+1]);sum[node]=sum[node*2]+sum[node*2+1]}private fun update(node:Int,left:Int,right:Int,index:Int){if(left==right){maximum[node]=remaining[index];sum[node]=remaining[index].toLong();return};val middle=(left+right)/2;if(index<=middle)update(node*2,left,middle,index)else update(node*2+1,middle+1,right,index);pull(node)}private fun find(node:Int,left:Int,right:Int,maxRow:Int,k:Int):Int{if(left>maxRow||maximum[node]<k)return -1;if(left==right)return left;val middle=(left+right)/2;val result=find(node*2,left,middle,maxRow,k);return if(result>=0)result else find(node*2+1,middle+1,right,maxRow,k)}private fun query(node:Int,left:Int,right:Int,maxRow:Int):Long{if(left>maxRow)return 0;if(right<=maxRow)return sum[node];val middle=(left+right)/2;return query(node*2,left,middle,maxRow)+query(node*2+1,middle+1,right,maxRow)}fun gather(k:Int,maxRow:Int):IntArray{val row=find(1,0,n-1,maxRow,k);if(row<0)return intArrayOf();val start=m-remaining[row];remaining[row]-=k;update(1,0,n-1,row);return intArrayOf(row,start)}fun scatter(kValue:Int,maxRow:Int):Boolean{if(query(1,0,n-1,maxRow)<kValue)return false;var k=kValue;while(k>0){while(first<n&&remaining[first]==0)first++;val take=minOf(k,remaining[first]);remaining[first]-=take;k-=take;update(1,0,n-1,first)};return true}}
